import {button,icon,esc,phraseText,quotedText} from './ui.js';
import {lessonExplanation} from './lesson-explanation.js';
import {lessonNumberWithVideo} from './video-lesson-state.js';
import {scenarioProgress,scenarioTitle} from './scenario-state.js';
export function renderRoleplay(s,top,l,c){
 const sceneImage=c.image?`<img class="scenario-image" src="${esc(c.image)}" alt="" width="960" height="480" decoding="async">`:'';
 const p=scenarioProgress(s),x=c.items[p.index],jp=s.courseDirection==='ja-ko',ui=jp?'ja':'ko',lang=jp?'ko':'ja',label=(ko,ja)=>jp?ja:ko;
 const partner=c.partner||label('직원','スタッフ');
 const progress=p.phase==='intro'?0:Math.round((p.index+(p.checked?1:0))/3*100);
 const heading=top(`${lessonNumberWithVideo(s,l.number[s.courseDirection])}. ${scenarioTitle(s,l)}`);
 const bar=`<div class="lesson-progress" role="progressbar" aria-label="${label('학습 진행률','学習の進み具合')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"><span style="width:${progress}%"></span></div>`;
 if(p.phase==='intro')return `${heading}${bar}<main class="page scenario-page roleplay-intro ${c.image?'scenario-illustrated':''}" lang="${ui}">${sceneImage}<h1>${esc(scenarioTitle(s,l))}</h1><p>${quotedText(c.scene)}</p>${button(label('대화 시작하기','会話を始める'),'scenario-next')}</main>`;
 const bubble=(line,parts,part,who,translation='')=>`<article class="roleplay-bubble ${part==='answer'||part.endsWith(':answer')?'roleplay-self':''}"><small>${who}</small><div class="audio-text-row"><p lang="${lang}">${c.chat&&lang==='ko'?esc(line):phraseText(line,parts)}</p>${button(icon('sound'),'scenario-audio','icon-button',`data-id="${part}" aria-label="${label('다시 듣기','もう一度聞く')}"`)}</div>${translation?`<details><summary>${label('뜻 보기','意味を見る')}</summary><p lang="${ui}">${quotedText(translation)}</p></details>`:''}</article>`;
 const choices=[...x.others];choices.splice(l.answers?.[p.index]??p.index,0,x.answer);
 const meanings=[...(x.otherMeanings||[])];meanings.splice(l.answers?.[p.index]??p.index,0,x.answerMeaning);
 const transcript=(count,title)=>`<details class="chat-history"><summary>${title}</summary><div class="roleplay-conversation">${c.items.slice(0,count).map((v,i)=>bubble(v.text,v.phrases,`${i}:prompt`,esc(partner),v.meaning)+bubble(v.answer,v.answerParts,`${i}:answer`,label('나','自分'),v.answerMeaning)+bubble(v.reply,v.replyParts,`${i}:reply`,esc(partner),v.replyMeaning)).join('')}</div></details>`;
 return `${heading}${bar}<main class="page scenario-page roleplay-page ${c.chat?'chat-page':''} ${c.image?'scenario-illustrated':''}" lang="${ui}">${!c.firstTurnImageOnly||p.index===0&&!p.checked?sceneImage:''}<div class="roleplay-scene"><p>${quotedText(x.prompt)}</p></div>${c.chat&&p.index>0?transcript(p.index,label('앞 대화 보기','これまでの会話')):''}<section class="roleplay-conversation" aria-label="${label('대화','会話')}">${bubble(x.text,x.phrases,'prompt',esc(partner),x.meaning)}${p.checked?`${bubble(x.answer,x.answerParts||undefined,'answer',label('나','自分'),x.answerMeaning)}<div role="status">${bubble(x.reply,x.replyParts,'reply',esc(partner),x.replyMeaning)}</div>`:''}</section>${!p.checked?`<div class="scenario-choices">${choices.map((o,i)=>{const answer=l.answers?.[p.index]??p.index,choice=i===answer?0:i<answer?i+1:i;return button(c.chat&&lang==='ko'?esc(o):phraseText(o,o===x.answer?x.answerParts||undefined:undefined),'scenario-select',`secondary${p.selected===i?' selected':''}`,`data-id="${i}" lang="${lang}" aria-pressed="${p.selected===i}"${c.chat?` data-choice-audio="choice:${choice}"`:''}`);}).join('')}</div>${p.retry?`<p class="scenario-feedback lesson-verdict" role="status">${label('다시 골라 보세요.','もう一度選んでみましょう。')}</p>`:''}${c.chat?`<details class="chat-choice-meanings"><summary>${label('선택지 뜻 보기','選択肢の意味')}</summary><ol>${meanings.map(m=>`<li>${quotedText(m)}</li>`).join('')}</ol></details>`:''}`:''}${p.checked?lessonExplanation(x.hint,jp):''}${c.chat&&p.checked&&p.index===2?transcript(3,label('완성된 대화 보기','完成した会話を見る')):''}<div class="button-pair">${button(label('이전','戻る'),'scenario-previous','secondary')}${p.checked?button(p.index===2?label('학습 마치기','学習を終える'):label('계속하기','続ける'),'scenario-next'):button(c.chat?label('보내기','送る'):label('답하기','答える'),'scenario-check','primary',p.selected===null?'disabled':'')}</div></main>`;
}
